def copy_side_to_genre(apps, schema_editor):
    Genre = apps.get_model("hear", "Genre")

    with schema_editor.connection.cursor() as cursor:
        cursor.execute("SELECT uuid, side FROM htmt_api_criteria WHERE type_id = %s", [int(CriteriaTypePks.GENRE)])
        genre_side_by_criteria_uuid = cursor.fetchall()

    # `bulk_create` doesn't support multi-table-inherited models (it would need to insert
    # into both `htmt_api_criteria` and `htmt_api_genre`, but the parent row already exists here).
    for criteria_uuid, side in genre_side_by_criteria_uuid:
        Genre(criteria_ptr_id=criteria_uuid, side=side).save_base(raw=True, force_insert=True)


